from __future__ import annotations
import base64, gzip
from pathlib import Path
import render

ROOT = Path(__file__).resolve().parent
OUT = ROOT / "tmp_sports_output"
OUT.mkdir(exist_ok=True)
BLOBS = {'528_cv.json': '', '528_cl.json': '', '529_cv.json': '', '529_cl.json': ''}
for name, blob in BLOBS.items():
    (OUT / name).write_bytes(gzip.decompress(base64.b64decode(blob)))
jobs = [
    ("cv","528_cv.json","JOB-2026-000528_Southampton_Data_Scientist_CV.html","JOB-2026-000528_Southampton_Data_Scientist_CV.pdf","JOB-2026-000528_composition.json"),
    ("cl","528_cl.json","JOB-2026-000528_Southampton_Data_Scientist_CL.html","JOB-2026-000528_Southampton_Data_Scientist_CL.pdf",None),
    ("cv","529_cv.json","JOB-2026-000529_Manchester_City_Performance_Data_Scientist_CV.html","JOB-2026-000529_Manchester_City_Performance_Data_Scientist_CV.pdf","JOB-2026-000529_composition.json"),
    ("cl","529_cl.json","JOB-2026-000529_Manchester_City_Performance_Data_Scientist_CL.html","JOB-2026-000529_Manchester_City_Performance_Data_Scientist_CL.pdf",None),
]
blocked=[]
for kind,payload,html,pdf,comp in jobs:
    failures=render.render(kind, OUT/payload, OUT/html, OUT/pdf, OUT/comp if comp else None)
    if failures:
        blocked.append((pdf, failures))
if blocked:
    for pdf, failures in blocked:
        print("BLOCKED", pdf)
        for code, detail in failures:
            print(f"[{code}] {detail}")
    raise SystemExit(2)
print("SPORTS PRODUCTION RENDER CLEAN")
